{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "INS018_055, a fluorophenyl/piperazine/amide heteroaromatic compound, showed good oral bioavailability in healthy volunteers, supporting high F for the query which shares the piperazine-amide and fluorophenyl motifs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Tofacitinib, which shares N-methyl amino heteroaryl, amide, and nitrile functionalities with the query, has an absolute oral bioavailability of approximately 74% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Zolpidem, a heteroaromatic amide with structural similarity to the query's core, has an absolute human oral bioavailability of about 72%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Basmisanil, a fluorophenyl/heteroaryl amide, showed approximately 75% absolute oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Darapladib, a lipophilic fluorophenyl/amide/thiazole compound, has low absolute bioavailability of about 12%, but its very high lipophilicity and poor solubility are not shared to the same degree by the query's ionizable piperazine and hydroxyl groups, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a moderately sized heteroaromatic amide with a basic piperazine, fluorophenyl, and nitrile-thiazole motifs. Multiple structurally related kinase inhibitors and heteroaromatic amides with similar polarity and solubility features show high human absolute oral bioavailability (67-90%), while the low-F comparators are either much more lipophilic/poorly soluble or polar nucleoside-like and do not transfer well. Therefore high (F >= 20%) is better supported.",
  "evidence_gaps": [
    "No direct human pharmacokinetic or absolute oral bioavailability data are available for the query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.22), limiting quantitative transferability.",
    "No experimental solubility, permeability, efflux, or first-pass metabolism data are available for the query.",
    "Formulation-dependent bioavailability is unknown for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

